using UnityEngine;
namespace Conquest.WorldMap {
 [RequireComponent(typeof(WorldMapCampaignController))]
 public sealed class WorldMapCampaignHud : MonoBehaviour {
  WorldMapCampaignController c;GUIStyle title,body,button,label;
  static readonly Color Bronze=new Color(.66f,.47f,.25f),Ink=new Color(.08f,.10f,.11f),Ivory=new Color(.94f,.89f,.76f);
  void Awake(){c=GetComponent<WorldMapCampaignController>();}
  void Styles(){if(title!=null)return;title=new GUIStyle(GUI.skin.label){fontSize=20,fontStyle=FontStyle.Bold};title.normal.textColor=Ivory;body=new GUIStyle(GUI.skin.label){fontSize=14,wordWrap=true};body.normal.textColor=Ivory;button=new GUIStyle(GUI.skin.button){fontSize=14,padding=new RectOffset(12,12,8,8)};label=new GUIStyle(body){alignment=TextAnchor.MiddleCenter,fontStyle=FontStyle.Bold};}
  public static void Panel(Rect r){var previous=GUI.color;GUI.color=Bronze;GUI.DrawTexture(r,Texture2D.whiteTexture);GUI.color=Ink;GUI.DrawTexture(new Rect(r.x+2,r.y+2,r.width-4,r.height-4),Texture2D.whiteTexture);GUI.color=previous;}
  public bool SelectAt(Vector2 screen){var ray=c.mapCamera.ScreenPointToRay(screen);var hits=Physics.RaycastAll(ray,10000,~0,QueryTriggerInteraction.Collide);System.Array.Sort(hits,(a,b)=>a.distance.CompareTo(b.distance));foreach(var h in hits){var target=h.collider.GetComponentInParent<WorldMapSettlementTarget>();if(target){c.selectedSettlement=target;return true;}if(!h.collider.isTrigger)return false;}c.selectedSettlement=null;return false;}
  public void Select(WorldMapSettlementTarget target){c.selectedSettlement=target;}
  void OnGUI(){Styles();float width=Mathf.Min(560,Screen.width-24);var top=new Rect(12,12,Mathf.Min(470,Screen.width-24),64);var bottom=new Rect((Screen.width-width)/2,Screen.height-74,width,62);var card=new Rect((Screen.width-width)/2,Screen.height-280,width,172);Panel(top);GUI.Label(new Rect(28,20,420,27),"BRONZE AGE  /  CAMPAÑA",title);GUI.Label(new Rect(28,48,420,20),"Clic: ciudad · doble clic: destino terrestre",body);
   Panel(bottom);GUI.Label(new Rect(bottom.x+12,bottom.y-24,width,22),c.travelStatus,body);if(GUI.Button(new Rect(bottom.x+12,bottom.y+12,155,36),"Seguir jugador",button)){c.follow=true;c.focus=c.actor.position;}if(GUI.Button(new Rect(bottom.x+177,bottom.y+12,160,36),c.moving?"Detener viaje":"Ir a ciudad B",button)&&!c.authoritativePosition){if(c.moving)c.StopTravel();else c.TravelTo(c.cityB.GetComponent<WorldMapSettlementTarget>().entrance);}GUI.Label(new Rect(bottom.x+350,bottom.y+12,width-360,38),c.RemainingDistance.ToString("F0")+" u · "+(c.RemainingDistance/c.movementSpeed).ToString("F0")+" s",body);
   // Labels are also clickable targets, avoiding tiny models at distant zoom levels.
   foreach(var target in new[]{c.cityA?c.cityA.GetComponent<WorldMapSettlementTarget>():null,c.cityB?c.cityB.GetComponent<WorldMapSettlementTarget>():null}){if(!target)continue;var p=c.mapCamera.WorldToScreenPoint(target.transform.position+Vector3.up*65);if(p.z<=0)continue;var r=new Rect(p.x-95,Screen.height-p.y-14,190,28);if(r.y<90||r.yMax>card.y&&c.selectedSettlement)continue;Panel(r);if(GUI.Button(r,target.displayName,label)){c.selectedSettlement=target;Event.current.Use();}}
   if(c.selectedSettlement){Panel(card);var t=c.selectedSettlement;GUI.Label(new Rect(card.x+18,card.y+12,width-85,28),t.displayName,title);if(GUI.Button(new Rect(card.xMax-46,card.y+10,32,28),"×",button))c.selectedSettlement=null;GUI.Label(new Rect(card.x+18,card.y+46,width-36,23),t.regionName+"  ·  Nivel "+t.level,body);var distance=t.DistanceFrom(c.actor.position);GUI.Label(new Rect(card.x+18,card.y+74,width-36,34),c.CanEnterSelected?"Estás junto al acceso. Puedes entrar.":"Acércate al acceso · faltan "+Mathf.Max(0,distance-c.entryDistance).ToString("F0")+" u",body);GUI.enabled=c.CanEnterSelected;if(GUI.Button(new Rect(card.x+18,card.y+118,180,38),"Entrar",button))c.RequestSelectedEntry();GUI.enabled=true;GUI.Label(new Rect(card.x+212,card.y+126,width-232,26),"",body);if(GUI.Button(new Rect(card.x+212,card.y+118,180,38),"Acercarse",button))c.TravelTo(t.entrance);}
   var e=Event.current;if(e.type==EventType.KeyDown&&e.keyCode==KeyCode.Escape){c.selectedSettlement=null;e.Use();}
   if(top.Contains(e.mousePosition)||bottom.Contains(e.mousePosition)||(c.selectedSettlement&&card.Contains(e.mousePosition))||(c.showDiagnostics&&new Rect(18,18,320,410).Contains(e.mousePosition)))return;
   if(e.type==EventType.MouseDown&&e.button==0){var pointer=new Vector2(e.mousePosition.x,Screen.height-e.mousePosition.y);if(!SelectAt(pointer)&&e.clickCount==2){var ray=c.mapCamera.ScreenPointToRay(pointer);if(Physics.Raycast(ray,out var hit,10000,~0,QueryTriggerInteraction.Ignore)&&hit.collider is TerrainCollider)c.TravelTo(hit.point);}e.Use();}
   if(e.type==EventType.ScrollWheel){c.viewSize=Mathf.Clamp(c.viewSize*Mathf.Exp(e.delta.y*.08f),c.minZoom,c.maxZoom);e.Use();}
   if(e.type==EventType.MouseDrag&&e.button==1){c.yaw+=e.delta.x*.25f;c.pitch=Mathf.Clamp(c.pitch+e.delta.y*.25f,35,70);e.Use();}
  }
 }
}
